import {drawFiniteReference} from './finite-crystal-reference.mjs';
import {chemicalRegistry,chemicalImage,openChemical} from './chemical-viewer.mjs';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let registryPromise;
let productReferencePromise;
async function productIdentity(host,r){
 if(!['veinot1997','yao1998','stiger1999'].includes(r.lineage?.source_group))return;
 productReferencePromise??=fetch(new URL('assets/chemical-registry/product-bindings.json',import.meta.url),{cache:'no-store'}).then(r=>r.json());
 const refs=await productReferencePromise,entryId=refs.recordBindings[r.record_id];
 if(entryId){const data=await chemicalRegistry(),entry=data.entries.get(entryId);if(entry){const card=el('article',undefined,'crystal-reference-card');card.append(el('h3',entry.model3dPath?'Product molecular structure':r.lineage?.source_group==='stiger1999'?'Supported nanocrystal structure':r.lineage?.source_group==='stiger1999'?'Supported nanocrystal structure':r.lineage?.source_group==='yao1998'?'Polymer and composite structure':'Surface functionalization'),chemicalImage(entry),el('p',entry.caption||entry.depictionKind));const b=el('button',entry.model3dPath?'Rotate molecular reference ↗':['yao1998','stiger1999'].includes(r.lineage?.source_group)?'Enlarge product representation ↗':'Enlarge surface representation ↗','molecule-link');b.type='button';b.onclick=()=>openChemical(entry);card.append(b);host.append(card);}}
 if(r.lineage?.source_group==='stiger1999')host.append(el('p','The paper assigns FCC silver using the original SAED pattern and tabulated spacings. No refined Ag/Si interface or measured atomic coordinates are supplied. A verified local Ag crystal reference is unavailable; no sample CIF or atomistic interface is invented. Product diagrams are schematic, and bare-Si controls retain their own identity.','guide-notice'));
 if(r.lineage?.source_group==='veinot1997'&&(r.record_id.includes('-ester-')||r.record_id.endsWith('-qdoh')||r.record_id.endsWith('-characterization')))host.append(el('p','The supplied article does not assign a CdS polymorph or provide atomic coordinates. The surface representation shows a proposed connectivity motif, not a measured particle geometry or ligand count. No sample CIF is available.','guide-notice'));
 if(r.lineage?.source_group==='yao1998'&&!/resin-conditioning|cadmium-loading/.test(r.record_id))host.append(el('p','For the principal samples a and b, the paper assigns cubic zinc blende to the CdS component from X-ray diffraction. It supplies no atomic coordinates or sample CIF. A verified cubic CdS reference structure is not available in this local collection. Polymer motifs and particle cross sections are explanatory representations; they do not reconstruct measured atomic positions.','guide-notice'));
}
const colors={Cd:'#d9af67',Se:'#689db3',O:'#ce6374',Zn:'#6c96ba',In:'#91a3c6',P:'#d4a457',Cs:'#9983bd',Pb:'#6b91aa',Br:'#b78654',Co:'#789baa',Fe:'#c48c59',Ir:'#7993a7',X:'#9575b0'};
export async function mountCrystalReferences(host,r){
 if(!host)return;host.replaceChildren();await productIdentity(host,r);registryPromise??=fetch(new URL('assets/crystal-references/registry.json',import.meta.url),{cache:'no-store'}).then(r=>r.json());const data=await registryPromise;const entries=data.entries.filter(x=>(x.record_ids||[]).includes(r.record_id));if(!entries.length){if(r.lineage?.source_group==='heath1996')host.append(el('h3','Atomic structure data'),el('p','The supplied article reports microscopy and crystallinity evidence but provides no atomic coordinates or measured CIF. A verified Ge reference structure is not available in the current local collection; no downloadable sample structure is inferred from the lattice mismatch.','guide-notice'));return;}
 host.append(el('h3','Reference crystal structures'),el('p','Independent bulk references for comparison. The unit cell and extended lattice are illustrative references, not atom-by-atom reconstructions of the synthesized nanocrystal.','guide-notice'));const grid=el('div',undefined,'crystal-reference-grid');host.append(grid);
 for(const ref of entries){const card=el('article',undefined,'crystal-reference-card'),view=el('div',undefined,'crystal-reference-view');view.tabIndex=0;view.setAttribute('aria-label',ref.name+' interactive crystal viewer');card.append(el('h4',ref.name),view,el('small',ref.scope||ref.description));const downloads=el('div',undefined,'protocol-controls');for(const [label,url] of [['Download reference CIF ↓',new URL('assets/crystal-references/'+ref.cifPath,import.meta.url)],['Structure source ↗',ref.sourceUrl]]){const a=el('a',label);a.href=url;downloads.append(a);}card.append(downloads);grid.append(card);
 for(const item of ref.additionalDownloads||[]){const a=el('a',item.label+' ↓');a.href=new URL('assets/crystal-references/'+item.path,import.meta.url);downloads.append(a);}
 if(ref.sourceLinkLabel)downloads.children[1].textContent=ref.sourceLinkLabel+' ↗';
 if(!window.$3Dmol)continue;
 const model=await(await fetch(new URL('assets/crystal-references/'+ref.modelPath+'?sha='+ref.modelSha256,import.meta.url))).json(),v=model.cellVectors;const viewer=$3Dmol.createViewer(view,{backgroundColor:'#f5f9fc'});let extent=1,finiteModel=null;
 const point=(i,j,k)=>({x:i*v[0][0]+j*v[1][0]+k*v[2][0],y:i*v[0][1]+j*v[1][1]+k*v[2][1],z:i*v[0][2]+j*v[1][2]+k*v[2][2]});
 function draw(n){extent=n;viewer.clear();let aa=[];for(let i=0;i<n;i++)for(let j=0;j<n;j++)for(let k=0;k<n;k++){const off=point(i,j,k);for(const a of model.atoms)aa.push({serial:aa.length,elem:a.element??a.elem,x:a.x+off.x,y:a.y+off.y,z:a.z+off.z,properties:a.properties});}viewer.addModel().addAtoms(aa);for(const species of new Set(aa.map(a=>a.elem)))viewer.setStyle({elem:species},{sphere:{radius:species==='X'?.32:species==='O'?.26:.38,color:colors[species]||'#7894a7'}});
 for(let axis=0;axis<3;axis++)for(const b of [0,n])for(const c of [0,n]){const start=[b,c];start.splice(axis,0,0);const end=[...start];end[axis]=n;viewer.addLine({start:point(...start),end:point(...end),color:'#89a1b2',linewidth:1});}
 viewer.zoomTo();viewer.rotate(15,'y');viewer.rotate(-12,'x');viewer.render();}
 draw(1);const controls=el('div',undefined,'protocol-controls'),caption=el('p','','guide-notice');const cellCaption=`${ref.spaceGroup} · a=${model.cell.a}, b=${model.cell.b}, c=${model.cell.c} Å; α=${model.cell.alpha}°, β=${model.cell.beta}°, γ=${model.cell.gamma}°. Drag to rotate; scroll to zoom.`;caption.textContent=cellCaption;for(const [label,n] of [['Unit cell',1],['2 × 2 × 2 lattice',2]]){const b=el('button',label);b.type='button';b.onclick=()=>{draw(n);caption.textContent=cellCaption;};controls.append(b);}card.insertBefore(controls,view);card.append(caption);
 if(ref.finiteModelPath){const b=el('button','Illustrative finite particle');b.type='button';b.onclick=async()=>{try{finiteModel??=await(await fetch(new URL('assets/crystal-references/'+ref.finiteModelPath+'?sha='+ref.finiteModelSha256,import.meta.url))).json();drawFiniteReference(viewer,finiteModel);extent=0;caption.textContent=ref.finiteCaption;}catch(e){caption.textContent='Reference model unavailable: '+e.message;}};controls.append(b);}
 if(ref.mixedOccupancy){const sites=[...new Set(model.atoms.filter(a=>a.mixed_site).map(a=>(a.components||[]).map(c=>c.element+' '+c.occupancy).join(' / ')))];card.append(el('p','Purple markers are statistically mixed Co/Fe sites, not an element X or an ordered assignment. Site occupancies: '+sites.join('; ')+'.','guide-notice'));}
 view.onkeydown=e=>{const turns={ArrowLeft:[-12,'y'],ArrowRight:[12,'y'],ArrowUp:[-12,'x'],ArrowDown:[12,'x']}[e.key];if(turns)viewer.rotate(...turns);else if(e.key==='Home'){if(extent===0)drawFiniteReference(viewer,finiteModel);else draw(extent);}else if(['+','='].includes(e.key))viewer.zoom(1.15);else if(e.key==='-')viewer.zoom(1/1.15);else return;e.preventDefault();viewer.render();};const observer=new ResizeObserver(()=>{if(view.isConnected){viewer.resize();viewer.render();}else{viewer.clear();observer.disconnect();}});observer.observe(view);
 }
}
